INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (0.0, 20026, 190801, "カリン", 3, 2, "2022/04/18 15:00:00", -416.5, 54, 2.801, 1, "2030/01/01 14:59:59", "受け取ることができる\n報酬があるようです\n確認してみてください", 20026003);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (0.0, 20026, 190801, "カリン", 4, 2, "2022/04/18 15:00:00", -416.5, 54, 0.0, 2, "2030/01/01 14:59:59", "報酬がもらえますよ！\nチェックしてみてください", 20026004);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (0.0, 20026, 190801, "カリン", 5, 1, "2022/04/18 15:00:00", -416.5, 57, 0.0, 1, "2030/01/01 14:59:59", "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 20026005);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (0.0, 20026, 190801, "カリン", 1, 2, "2022/04/18 15:00:00", -363.0, 55, 5.506, 1, "2030/01/01 14:59:59", "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 20026006);
