INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (0.0, 20026, 190801, "カリン", 3, 1, "2022/04/18 15:00:00", -363.0, 56, 1.539, 2, "2030/01/01 14:59:59", "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 20026008);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (0.0, 20026, 190801, "カリン", 4, 1, "2022/04/18 15:00:00", -363.0, 56, 1.875, 2, "2030/01/01 14:59:59", "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", 20026009);
